pub fn get_spell_description(id: u32) -> Option<&'static str> {
    SPELL_DESCRIPTIONS
        .binary_search_by_key(&id, |(spell_id, _)| *spell_id)
        .ok()
        .map(|idx| SPELL_DESCRIPTIONS[idx].1)
}
